    import math

def evaluatePostfix(arr):
    st = []

    for token in arr:

        # If it's an operand (number), push it onto the stack
        if token[0].isdigit() or (len(token) > 1 and token[0] == '-'):
            st.append(int(token))

        # Otherwise, it must be an operator
        else:
            val1 = st.pop()
            val2 = st.pop()

            if token == '+':
                st.append(val2 + val1)
            elif token == '-':
                st.append(val2 - val1)
            elif token == '*':
                st.append(val2 * val1)
            elif token == '/':
                st.append(val2 // val1)
            elif token == '^':
                st.append(int(math.pow(val2, val1)))
    return st.pop()

